def clean(records):
    """
    Clean records:
    - Remove empty rows
    - Convert field names to snake_case
    - Reject records missing or empty 'id'
    """
    processed = []
    rejects = []
    for record in records:
        if not any(v for v in record.values() if v.strip()):
            continue  # empty row
        cleaned = {snake_case(k): v for k, v in record.items()}
        if 'id' not in cleaned or not str(cleaned.get('id', '')).strip():
            rejects.append(cleaned)
        else:
            processed.append(cleaned)
    return processed, rejects
